    /**
     * Tests getting all JobFamilys.
     *
     * @return    Collection
     */
    public List<JobFamily> testGetAll() throws Throwable {
    LOGGER.info( "JobFamilyTest:testGetAll() - Retrieving Collection of JobFamilys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all JobFamily : " );
    List<JobFamily> collection  = null;

    try {
        // call the static get method on the JobFamilyService
        collection = service.getAllJobFamily();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            JobFamily currEntity  = null;
            Iterator<JobFamily> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getJobFamilyId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

